# Generate K_{8,8} as a maximal triangle-free graph with 16 vertices
# Partition 1: vertices 0-7
# Partition 2: vertices 8-15

edges = []
for u in range(8):
    for v in range(8, 16):
        edges.append((u, v))

print(f"Number of edges: {len(edges)}")
print("First 10 edges:", edges[:10])

# Verify triangle-free
def is_triangle_free(n, edges):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[u]:
                    if w > v and w in adj[v]:
                        return False, (u, v, w)
    return True, None

triangle_free, triangle = is_triangle_free(16, edges)
print(f"Triangle-free: {triangle_free}")
if not triangle_free:
    print(f"Triangle found: {triangle}")

# Verify maximal: for every non-edge (u,v), there should be a w such that (u,w) and (v,w) are edges
def is_maximal_triangle_free(n, edges):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for u in range(n):
        for v in range(u+1, n):
            if v not in adj[u]:  # non-edge
                # Check if there's a common neighbor
                common = adj[u] & adj[v]
                if not common:
                    return False, (u, v)
    return True, None

maximal, non_maximal_pair = is_maximal_triangle_free(16, edges)
print(f"Maximal: {maximal}")
if not maximal:
    print(f"Non-maximal pair: {non_maximal_pair}")
